const paths={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M15 3a4 4 0 0 1 0 8"/><circle cx="9" cy="7" r="4"/>',card:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20M6 15h4"/>',check:'<path d="M9 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h4m5-14 5 5-5 5m-7-5h12"/>',chart:'<path d="M4 3v18h17M9 16v-5m5 5V6m5 10V9"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 12h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',warning:'<path d="m12 3 10 18H2zM12 9v5m0 3v.2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',money:'<path d="M12 2v20m5-16H9a3 3 0 0 0 0 6h6a3 3 0 0 1 0 6H6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.dashboard}</svg>`;
function icons(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
const initial=[{id:1,name:'Santiago Rodríguez',dni:'1023456789',plan:'Full Access',expiry:'2026-11-06',status:'Activo',email:'santiago.r@email.com',color:'#374837'},{id:2,name:'Valentina Martínez',dni:'1034567890',plan:'Plan Premium',expiry:'2026-10-08',status:'Activo',email:'valentina.m@email.com',color:'#443b4b'},{id:3,name:'Andrés López',dni:'1045678901',plan:'Plan Básico',expiry:'2026-10-01',status:'Vencido',email:'andres.l@email.com',color:'#493c31'},{id:4,name:'Camila Torres',dni:'1056789012',plan:'Full Access',expiry:'2026-11-15',status:'Activo',email:'camila.t@email.com',color:'#35444c'},{id:5,name:'Daniel Herrera',dni:'1067890123',plan:'Plan Básico',expiry:'2026-09-20',status:'Inactivo',email:'daniel.h@email.com',color:'#443e33'},{id:6,name:'Laura Gómez',dni:'1078901234',plan:'Plan Premium',expiry:'2026-10-10',status:'Activo',email:'laura.g@email.com',color:'#473642'},{id:7,name:'Mateo Ramírez',dni:'1089012345',plan:'Full Access',expiry:'2026-12-02',status:'Activo',email:'mateo.r@email.com',color:'#33433c'},{id:8,name:'Isabella Rojas',dni:'1090123456',plan:'Plan Básico',expiry:'2026-09-28',status:'Vencido',email:'isabella.r@email.com',color:'#423949'}];
let members,entries;try{members=JSON.parse(localStorage.getItem('pulse-members'))||initial;entries=JSON.parse(localStorage.getItem('pulse-entries'))||[];}catch{members=initial;entries=[];}
const referenceDate='2026-10-06';const money=n=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(n);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const status=m=>m.status==='Inactivo'?'Inactivo':m.expiry<referenceDate?'Vencido':m.status;
const date=s=>new Intl.DateTimeFormat('es-CO',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(s+'T12:00:00'));
function save(){try{localStorage.setItem('pulse-members',JSON.stringify(members));localStorage.setItem('pulse-entries',JSON.stringify(entries));}catch{toast('No se pudo guardar en este navegador.');}}
let page='dashboard',filter='',query='',pageNumber=1,editing=null;
const sections=[['dashboard','Dashboard','dashboard'],['socios','Socios','users'],['membresias','Membresías','card'],['check-in','Check-in','check'],['reportes','Reportes','chart']];
const subtitles={dashboard:'Todo lo que necesitas para mantener el ritmo.',socios:'Cada socio cuenta. Gestiona tu comunidad desde aquí.',membresias:'Planes que se adaptan al ritmo de tus socios.','check-in':'Un paso más cerca de su próxima meta.',reportes:'Convierte los números en mejores decisiones.'};
function render(){document.getElementById('nav').innerHTML=sections.map(([id,name,i])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''} aria-label="${name}">${icon(i)}<span class="nav-text">${name}</span></button>`).join('');let title=sections.find(s=>s[0]===page)[1];document.getElementById('crumb').textContent=title;document.getElementById('page-title').innerHTML=title+' <span class="title-dot">.</span>';document.getElementById('page-subtitle').textContent=subtitles[page];document.getElementById('content').innerHTML=page==='dashboard'?dashboard():page==='socios'?table():page==='check-in'?checkPage():page==='membresias'?plans():reports();icons();bind();}
function kpis(){const active=members.filter(m=>status(m)==='Activo').length;const expiring=members.filter(m=>status(m)==='Activo'&&m.expiry<='2026-10-13').length;return `<div class="kpis"><article class="card kpi"><div class="kpi-top">Socios Activos<span class="kpi-icon">${icon('users')}</span></div><div class="kpi-number">${active.toString().padStart(2,'0')}</div><div class="kpi-bottom"><span class="trend">↗ 12,8%</span> respecto al mes anterior</div></article><article class="card kpi"><div class="kpi-top">Ingresos del Día<span class="kpi-icon">${icon('money')}</span></div><div class="kpi-number"><small>$</small> 845.000</div><div class="kpi-bottom"><span class="trend">↗ 8,2%</span> respecto a ayer</div></article><article class="card kpi"><div class="kpi-top">Membresías por Vencer<span class="kpi-icon">${icon('clock')}</span></div><div class="kpi-number">${expiring.toString().padStart(2,'0')}</div><div class="kpi-bottom"><span class="trend orange">Próximos 7 días</span><button class="text-button" data-expiring>Ver socios →</button></div></article></div>`;}
function chart(){return `<article class="card"><div class="card-header"><div><h2>Afluencia de socios</h2><div class="card-subtitle">Cada visita es un paso hacia su mejor versión.</div></div><select class="select-small" id="chart-period" aria-label="Periodo del gráfico"><option value="week">Últimos 7 días</option><option value="previous">7 días anteriores</option></select></div><div class="chart" role="img" aria-label="Afluencia de socios en los últimos 7 días"><div class="axis"><span>200</span><span>150</span><span>100</span><span>50</span><span>0</span></div><div class="plot" id="plot">${bars(false)}</div></div><div class="chart-foot"><span><i></i> <b id="chart-total">${869+entries.length}</b> visitas en este periodo</span><span class="trend">↗ 16,4% vs. anterior</span></div></article>`;}
function bars(previous){const values=previous?[92,121,110,132,95,68,128]:[112,138,124,162,106,79,148+entries.length];return values.map((n,i)=>`<div class="bar-col ${i===6?'current':''}"><div class="bar" style="height:${n/200*85}%" title="${n} visitas">${i===6?`<span class="bar-value">${n} visitas</span>`:''}</div><span class="bar-label">${['Mié','Jue','Vie','Sáb','Dom','Lun','Mar'][i]}</span></div>`).join('');}
function quick(){return `<article class="card"><div class="card-header"><div><h2>Check-in rápido</h2><div class="card-subtitle">La energía empieza en la entrada.</div></div><span class="live"><i></i> EN VIVO</span></div><div class="quick-body"><form id="check-form"><label class="field-label" for="dni">Cédula del socio</label><div class="input-wrap">${icon('card')}<input id="dni" name="dni" inputmode="numeric" placeholder="Ingresa el número de cédula" required pattern="[0-9]{6,12}" autocomplete="off"></div><button class="primary" type="submit">${icon('check')} Registrar Ingreso ${icon('arrow')}</button></form><div id="check-result" role="status"><div class="alert">${icon('shield')}<div><strong>Listo para recibir a tus socios</strong><small>Ingresa una cédula para validar la membresía.</small></div></div></div><p class="quick-hint">Prueba: 1023456789 · Activo / 1045678901 · Vencido</p></div></article>`;}
function dashboard(){return kpis()+`<div class="middle">${chart()}${quick()}</div>`+table(true);}
function checkPage(){return `<div class="check-page"><div class="check-symbol">${icon('check')}</div>${quick()}<div class="example-label">EJEMPLOS DE VALIDACIÓN</div><div class="alert">${icon('shield')}<div><strong>Acceso Permitido</strong><small>Membresía activa. ¡A darlo todo!</small></div></div><div class="alert error">${icon('warning')}<div><strong>Membresía Vencida</strong><small>Renueva la membresía para habilitar el ingreso.</small></div></div></div>`;}
function filtered(){return members.filter(m=>(!filter||filter==='expiring'?(filter!=='expiring'||status(m)==='Activo'&&m.expiry<='2026-10-13'):status(m)===filter)&&`${m.name} ${m.dni}`.toLowerCase().includes(query.toLowerCase()));}
function table(compact=false){return `<article class="card table-card"><div class="table-header"><div><div class="table-title"><h2>${compact?'Socios recientes':'Todos los socios'}</h2><span class="counter">${members.length}</span></div><div class="card-subtitle">Una comunidad que no deja de crecer.</div></div><div class="table-tools"><label class="search">${icon('search')}<input id="member-search" placeholder="Buscar socio..." aria-label="Buscar socio por nombre o cédula" value="${escape(query)}"></label>${compact?'<button class="text-button" data-page="socios">Ver todos →</button>':`<select class="select-small" id="status-filter" aria-label="Filtrar por estado"><option value="">Todos los estados</option>${['Activo','Vencido','Inactivo','expiring'].map(s=>`<option value="${s}" ${filter===s?'selected':''}>${s==='expiring'?'Por vencer':s}</option>`).join('')}</select>`}</div></div><div class="table-scroll"><table><thead><tr><th>Nombre</th><th>Cédula</th><th>Plan actual</th><th>Fecha de vencimiento</th><th>Estado</th><th>Acciones</th></tr></thead><tbody id="member-rows">${rows(compact)}</tbody></table></div><div class="table-footer"><span id="table-count">${count(compact)}</span><div class="pagination">${compact?'<span>Actualizado hace un momento</span>':'<button id="prev-page" aria-label="Página anterior">‹</button><span id="page-number">'+pageNumber+'</span><button id="next-page" aria-label="Página siguiente">›</button>'}</div></div></article>`;}
function rows(compact){let list=filtered().slice(compact?0:(pageNumber-1)*6,compact?5:pageNumber*6);return list.length?list.map(m=>`<tr><td><div class="member-cell"><span class="avatar" style="background:${m.color||'#364536'}">${escape(m.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><span><strong>${escape(m.name)}</strong><small>${escape(m.email||'Nuevo socio')}</small></span></div></td><td>${escape(m.dni)}</td><td><span class="plan">${escape(m.plan)}</span></td><td>${date(m.expiry)}</td><td><span class="badge ${status(m)}"><i></i>${status(m)}</span></td><td><div class="row-actions"><button data-edit="${m.id}">Editar</button><button data-renew="${m.id}">Renovar ↗</button></div></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No hay socios que coincidan con esta búsqueda.</td></tr>';}
function count(compact){let n=filtered().length,start=compact?1:(pageNumber-1)*6+1;return n?`Mostrando ${start}–${Math.min(compact?5:pageNumber*6,n)} de ${n} socios`:'0 socios encontrados';}
function updateTable(){const compact=page==='dashboard';const max=Math.max(1,Math.ceil(filtered().length/6));pageNumber=Math.min(pageNumber,max);document.getElementById('member-rows').innerHTML=rows(compact);document.getElementById('table-count').textContent=count(compact);if(document.getElementById('page-number'))document.getElementById('page-number').textContent=pageNumber;bindRows();}
function plans(){return `<div class="plans">${[['Plan Básico',89000,'Tu primer paso hacia una vida activa.',['Acceso a zona de musculación','Horario de 6:00 a 16:00','Evaluación inicial']],['Full Access',139000,'Sin límites. Entrena a tu propio ritmo.',['Acceso a todas las zonas','Horario completo','Clases grupales incluidas']],['Plan Premium',199000,'Una experiencia a la altura de tus metas.',['Todos los beneficios Full Access','Entrenamiento personalizado','Asesoría nutricional']]].map(([name,price,desc,features])=>`<article class="card plan-card"><div class="eyebrow">MEMBRESÍA MENSUAL</div><h2>${name}</h2><p>${desc}</p><div class="plan-price">${money(price)} <small>/ mes</small></div><ul>${features.map(f=>`<li>${f}</li>`).join('')}</ul><p>${members.filter(m=>m.plan===name).length} socios en este plan</p><button class="secondary" data-plan="${name}">Asignar a nuevo socio →</button></article>`).join('')}</div>${table()}`;}
function reports(){return kpis()+`<div class="report-grid">${chart()}<article class="card report-stat"><h2>Control de accesos</h2><p class="card-subtitle">Ingresos registrados durante esta demostración</p><strong>${entries.length.toString().padStart(2,'0')}</strong><p class="card-subtitle">${entries.length?'Último ingreso: '+escape(entries.at(-1).name):'Registra el primer ingreso desde Check-in.'}</p><button class="secondary" id="export">${icon('chart')} Exportar socios (CSV)</button></article></div>`;}
function bindRows(){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openMember(Number(b.dataset.edit)));document.querySelectorAll('[data-renew]').forEach(b=>b.onclick=()=>{let m=members.find(x=>x.id===Number(b.dataset.renew));let base=m.expiry>referenceDate?m.expiry:referenceDate;let d=new Date(base+'T12:00:00');d.setDate(d.getDate()+30);m.expiry=d.toISOString().slice(0,10);m.status='Activo';save();render();toast(`Membresía de ${m.name.split(' ')[0]} renovada por 30 días`);});}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-expiring]').forEach(b=>b.onclick=()=>{filter='expiring';query='';pageNumber=1;page='socios';location.hash='socios';render();});document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{openMember();document.querySelector('[name="plan"]').value=b.dataset.plan;});const search=document.getElementById('member-search');if(search)search.oninput=()=>{query=search.value;pageNumber=1;updateTable();};const sf=document.getElementById('status-filter');if(sf)sf.onchange=()=>{filter=sf.value;pageNumber=1;updateTable();};const prev=document.getElementById('prev-page'),next=document.getElementById('next-page');if(prev)prev.onclick=()=>{pageNumber=Math.max(1,pageNumber-1);updateTable();};if(next)next.onclick=()=>{pageNumber=Math.min(Math.max(1,Math.ceil(filtered().length/6)),pageNumber+1);updateTable();};const form=document.getElementById('check-form');if(form)form.onsubmit=e=>{e.preventDefault();const dni=form.dni.value.trim(),m=members.find(x=>x.dni===dni);let allowed=m&&status(m)==='Activo';let title=allowed?'Acceso Permitido':m?(status(m)==='Vencido'?'Membresía Vencida':'Socio Inactivo'):'Socio no encontrado';let desc=allowed?`${m.name} · ${m.plan} · ¡Buen entrenamiento!`:m?`${m.name} · Contacta a recepción para habilitar el acceso.`:'Verifica la cédula o registra un nuevo socio.';document.getElementById('check-result').innerHTML=`<div class="alert ${allowed?'':'error'}">${icon(allowed?'shield':'warning')}<div><strong>${title}</strong><small>${escape(desc)}</small></div></div>`;if(allowed){entries.push({name:m.name,dni,time:new Date().toISOString()});save();if(document.getElementById('plot')){document.getElementById('plot').innerHTML=bars(false);document.getElementById('chart-total').textContent=869+entries.length;}form.reset();}};const cp=document.getElementById('chart-period');if(cp)cp.onchange=()=>{let old=cp.value==='previous';document.getElementById('plot').innerHTML=bars(old);document.getElementById('chart-total').textContent=old?746:869+entries.length;document.querySelector('.chart').setAttribute('aria-label',old?'Afluencia en los 7 días anteriores':'Afluencia en los últimos 7 días');};const ex=document.getElementById('export');if(ex)ex.onclick=exportCSV;bindRows();}
function navigate(id){page=id;filter='';query='';pageNumber=1;location.hash=id;render();}
function toast(message){let e=document.getElementById('toast');e.textContent=message;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),4000);}
function openMember(id){editing=id||null;const form=document.getElementById('member-form');form.reset();document.getElementById('dialog-title').textContent=id?'Editar socio':'Nuevo socio';if(id){const m=members.find(x=>x.id===id);for(const key of ['name','dni','plan','expiry','status'])form.elements[key].value=m[key];}else form.expiry.value='2026-11-06';document.getElementById('member-dialog').showModal();}
document.getElementById('new-member').onclick=()=>openMember();document.getElementById('close-dialog').onclick=()=>document.getElementById('member-dialog').close();document.getElementById('member-form').onsubmit=e=>{e.preventDefault();let form=e.target;const data=Object.fromEntries(new FormData(form));data.name=data.name.trim();if(!data.name){toast('Ingresa un nombre válido.');return;}if(members.some(m=>m.dni===data.dni&&m.id!==editing)){toast('Esta cédula ya está registrada.');return;}if(editing)Object.assign(members.find(x=>x.id===editing),data);else members.unshift({id:Date.now(),...data});save();document.getElementById('member-dialog').close();render();toast(editing?'Datos del socio actualizados':'Nuevo socio registrado');};
function exportCSV(){let cells=[['Nombre','Cédula','Plan','Vencimiento','Estado'],...members.map(m=>[m.name,m.dni,m.plan,m.expiry,status(m)])];let csv='\uFEFF'+cells.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='pulse-socios.csv';a.click();URL.revokeObjectURL(url);toast('Reporte de socios exportado');}
document.getElementById('notifications').onclick=()=>toast(`${members.filter(m=>status(m)==='Activo'&&m.expiry<='2026-10-13').length} membresías vencen en los próximos 7 días.`);document.getElementById('profile').onclick=()=>toast('Alex Castro · Administrador de la sede principal');window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(sections.some(s=>s[0]===target)&&page!==target){page=target;filter='';query='';pageNumber=1;render();}});if(sections.some(s=>s[0]===location.hash.slice(1)))page=location.hash.slice(1);render();
